        "code": {
          "coding": [
            {
              "system": "http://snomed.info/sct",
              "code": "128473001",
              "display": "Anterior uveitis"
            }
          ],
          "text": "Anterior uveitis"
        },
        "bodySite": [
          {
            "text": "Left eye"
          }
        ],
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Blood pressure"
